// Rows with a website and no email, gathered into ONE item so the Apify node runs
// once for the whole sheet (it runs once per incoming item).
const settings = $('Settings').first().json;
const host = (u) => String(u ?? '').trim().toLowerCase().replace(/^https?:\/\//, '').replace(/^www\./, '').split(/[\/?#]/)[0];
const rows = $input.all().map((i) => i.json)
  .filter((r) => host(r.Website))
  .filter((r) => !settings.onlyRowsWithoutEmail || !String(r.Email ?? '').trim())
  .slice(0, settings.maxRowsPerRun);
if (!rows.length) return [];
return [{ json: { urls: rows.map((r) => String(r.Website).trim()), rows: rows.map((r) => ({ Website: r.Website, domain: host(r.Website) })) } }];

// The actor returns one row per website: contacts, "none published" (emails: []),
// or an error row with no emails field at all. Pair each with its sheet row by domain.
const host = (u) => String(u ?? '').trim().toLowerCase().replace(/^https?:\/\//, '').replace(/^www\./, '').split(/[\/?#]/)[0];
const picked = $('Pick rows to fill in').first().json.rows;
const results = $input.all().map((i) => i.json);
const byDomain = new Map();
for (const r of results) {
  for (const key of [host(r.url), host(r.finalUrl), host(r.domain)]) if (key && !byDomain.has(key)) byDomain.set(key, r);
}
const today = new Date().toISOString().slice(0, 10);
return picked.map((row) => {
  const r = byDomain.get(row.domain);
  const out = { Website: row.Website, 'Enriched on': today };
  if (!r) {
    out['Enrichment note'] = 'not read';
  } else if (r.type === 'error') {
    out['Enrichment note'] = `couldn't read the site: ${r.error}`;
  } else {
    const social = r.social ?? {};
    const found = {
      Email: r.email, Phone: r.phone, LinkedIn: social.linkedin, Instagram: social.instagram,
      Facebook: social.facebook, 'Contact form': r.contactFormUrl,
    };
    for (const [k, v] of Object.entries(found)) if (v) out[k] = v;
    out['Enrichment note'] = Object.keys(found).some((k) => found[k]) ? `found on ${r.pagesReadCount} page(s)` : 'no contacts published';
  }
  return { json: out };
});
